      // Add support for dropdown suggestions
      function loadDropdownSuggestions() {
        // Collect all existing IDs and Meta-IDs
        const existingIds = [];
        const existingMetaIds = [];
        
        // Collect from Kastens
        Object.values(kastenData).forEach(kasten => {
          kasten.entries.forEach(entry => {
            if (entry.id) existingIds.push(entry.id);
            if (entry.metaId) existingMetaIds.push(entry.metaId);
          });
        });
        
        // Collect from Codexes
        Object.values(codexData).forEach(codex => {
          codex.entries.forEach(entry => {
            if (entry.id) existingIds.push(entry.id);
            if (entry.metaId) existingMetaIds.push(entry.metaId);
          });
        });
        
        // Setup listeners for ID field
        setupDropdownField('entry-id', 'id-suggestions', existingIds);
        setupDropdownField('entry-meta-id', 'meta-id-suggestions', existingMetaIds);
        setupDropdownField('codex-entry-id', 'codex-id-suggestions', existingIds);
        setupDropdownField('codex-entry-meta-id', 'codex-meta-id-suggestions', existingMetaIds);
        
        // Setup cross-references suggestions
        setupCrossRefSuggestions('entry-cross-refs', 'tags-suggestions', existingIds);
        setupCrossRefSuggestions('codex-entry-cross-refs', 'codex-tags-suggestions', existingIds);
      }
      
      function setupDropdownField(inputId, suggestionsId, items) {
        const input = document.getElementById(inputId);
        const suggestions = document.getElementById(suggestionsId);
        
        input.addEventListener('focus', () => showDropdownSuggestions(input, suggestions, items));
        input.addEventListener('input', () => showDropdownSuggestions(input, suggestions, items));
        
        // Hide suggestions when clicking outside
        document.addEventListener('click', (e) => {
          if (e.target !== input && !suggestions.contains(e.target)) {
            suggestions.classList.remove('active');
          }
        });
      }
      
      function showDropdownSuggestions(input, suggestions, items) {
        const inputValue = input.value.toLowerCase();
        
        // Filter items based on input
        const filteredItems = items.filter(item => 
          item.toLowerCase().includes(inputValue)
        );
        
        // Clear previous suggestions
        suggestions.innerHTML = '';
        
        // Add filtered items
        if (filteredItems.length > 0) {
          filteredItems.forEach(item => {
            const suggestionItem = document.createElement('div');
            suggestionItem.className = 'suggestion-item';
            suggestionItem.textContent = item;
            suggestionItem.addEventListener('click', () => {
              input.value = item;
              suggestions.classList.remove('active');
            });
            suggestions.appendChild(suggestionItem);
          });
          
          suggestions.classList.add('active');
        } else {
          suggestions.classList.remove('active');
        }
      }
      
      function setupCrossRefSuggestions(textareaId, suggestionsId, items) {
        const textarea = document.getElementById(textareaId);
        const suggestions = document.getElementById(suggestionsId);
        
        textarea.addEventListener('input', () => {
          // Get current line the cursor is on
          const cursorPos = textarea.selectionStart;
          const textValue = textarea.value;
          const lines = textValue.substring(0, cursorPos).split('\\n');
          const currentLine = lines[lines.length - 1].toLowerCase();
          
          // Show suggestions based on current line
          if (currentLine.trim() !== '') {
            const filteredItems = items.filter(item => 
              item.toLowerCase().includes(currentLine)
            );
            
            // Clear previous suggestions
            suggestions.innerHTML = '';
            
            // Add filtered items
            if (filteredItems.length > 0) {
              filteredItems.forEach(item => {
                const suggestionItem = document.createElement('div');
                suggestionItem.className = 'suggestion-item';
                suggestionItem.textContent = item;
                suggestionItem.addEventListener('click', () => {
                  // Replace current line with selected item
                  const textBeforeCursor = textValue.substring(0, cursorPos - currentLine.length);
                  const textAfterCursor = textValue.substring(cursorPos);
                  textarea.value = textBeforeCursor + item + textAfterCursor;
                  suggestions.classList.remove('active');
                  
                  // Set cursor position after inserted item
                  const newPos = textBeforeCursor.length + item.length;
                  textarea.setSelectionRange(newPos, newPos);
                  textarea.focus();
                });
                suggestions.appendChild(suggestionItem);
              });
              
              suggestions.classList.add('active');
            } else {
              suggestions.classList.remove('active');
            }
          } else {
            suggestions.classList.remove('active');
          }
        });
        
        // Hide suggestions when clicking outside
        document.addEventListener('click', (e) => {
          if (e.target !== textarea && !suggestions.contains(e.target)) {
            suggestions.classList.remove('active');
          }
        });
      }
      
      // Load suggestions on page load
      document.addEventListener('DOMContentLoaded', loadDropdownSuggestions);
      
